import unittest
from normalize import normalize_records
class Tests(unittest.TestCase):
    def test_contract(self):
        source = [{"id":1,"name":" A ","extra":1},{"id":True,"name":"B"},{"id":1,"name":"Other"},{"id":2,"name":" "},None,{"id":3,"name":"C"}]
        before = repr(source)
        self.assertEqual(normalize_records(source), [{"id":1,"name":"A"},{"id":3,"name":"C"}])
        self.assertEqual(repr(source), before)
if __name__ == "__main__": unittest.main()

